80:    struct CubeIndexEstimator
81:    {
82:      PtrStep<short2> volume;
83:
84:	  static __device__ __forceinline__ float isoValue() { return 0.f; }
85:
86:      __device__ __forceinline__ void
87:      readTsdf (int x, int y, int z, float& tsdf, int& weight) const
88:      {
89:        unpack_tsdf (volume.ptr (VOLUME_Y * z + y)[x], tsdf, weight);
90:      }
91:
92:      __device__ __forceinline__ int
93:      computeCubeIndex (int x, int y, int z, float f[8]) const
94:      {
95:        int weight;
96:        readTsdf (x,     y,     z,     f[0], weight); if (weight == 0) return 0;
97:        readTsdf (x + 1, y,     z,     f[1], weight); if (weight == 0) return 0;
98:        readTsdf (x + 1, y + 1, z,     f[2], weight); if (weight == 0) return 0;
99:        readTsdf (x,     y + 1, z,     f[3], weight); if (weight == 0) return 0;
100:        readTsdf (x,     y,     z + 1, f[4], weight); if (weight == 0) return 0;
101:        readTsdf (x + 1, y,     z + 1, f[5], weight); if (weight == 0) return 0;
102:        readTsdf (x + 1, y + 1, z + 1, f[6], weight); if (weight == 0) return 0;
103:        readTsdf (x,     y + 1, z + 1, f[7], weight); if (weight == 0) return 0;
104:
105:        // calculate flag indicating if each vertex is inside or outside isosurface
106:        int cubeindex;
107:        cubeindex = int(f[0] < isoValue());
108:        cubeindex += int(f[1] < isoValue()) * 2;
109:        cubeindex += int(f[2] < isoValue()) * 4;
110:        cubeindex += int(f[3] < isoValue()) * 8;
111:        cubeindex += int(f[4] < isoValue()) * 16;
112:        cubeindex += int(f[5] < isoValue()) * 32;
113:        cubeindex += int(f[6] < isoValue()) * 64;
114:        cubeindex += int(f[7] < isoValue()) * 128;
115:
116:        return cubeindex;
117:      }
118:    };
119:
120:    struct OccupiedVoxels : public CubeIndexEstimator
121:    {
122:      enum
123:      {        
124:        CTA_SIZE_X = 32,
125:        CTA_SIZE_Y = 8,
126:        CTA_SIZE = CTA_SIZE_X * CTA_SIZE_Y,
127:
128:        WARPS_COUNT = CTA_SIZE / Warp::WARP_SIZE
129:      };
130:
131:      mutable int* voxels_indeces;
132:      mutable int* vetexes_number;
133:      int max_size;
134:
135:      __device__ __forceinline__ void
136:      operator () () const
137:      {
138:        int x = threadIdx.x + blockIdx.x * CTA_SIZE_X;
139:        int y = threadIdx.y + blockIdx.y * CTA_SIZE_Y;
140:
141:        if (__all_sync (__activemask (), x >= VOLUME_X)
142:            || __all_sync (__activemask (), y >= VOLUME_Y))
143:          return;
144:
145:        int ftid = Block::flattenedThreadId ();
146:		int warp_id = Warp::id();
147:		int lane_id = Warp::laneId();
148:
149:        volatile __shared__ int warps_buffer[WARPS_COUNT];
150:
151:        for (int z = 0; z < VOLUME_Z - 1; z++)
152:        {
153:          int numVerts = 0;
154:          if (x + 1 < VOLUME_X && y + 1 < VOLUME_Y)
155:          {
156:            float field[8];
157:            int cubeindex = computeCubeIndex (x, y, z, field);
158:
159:            // read number of vertices from texture
160:            numVerts = (cubeindex == 0 || cubeindex == 255) ? 0 : tex1Dfetch (numVertsTex, cubeindex);
161:          }
162:
163:          int total = __popc (__ballot_sync (__activemask (), numVerts > 0));
164:		  if (total == 0)
165:			continue;
166:
167:          if (lane_id == 0)
168:          {
169:            int old = atomicAdd (&global_count, total);
170:            warps_buffer[warp_id] = old;
171:          }
172:          int old_global_voxels_count = warps_buffer[warp_id];
173:
174:          int offs = Warp::binaryExclScan (__ballot_sync (__activemask (), numVerts > 0));
175:
176:          if (old_global_voxels_count + offs < max_size && numVerts > 0)
177:          {
178:            voxels_indeces[old_global_voxels_count + offs] = VOLUME_Y * VOLUME_X * z + VOLUME_X * y + x;
179:            vetexes_number[old_global_voxels_count + offs] = numVerts;
180:          }
181:
182:          bool full = old_global_voxels_count + total >= max_size;
183:
184:          if (full)
185:            break;
186:
187:        } /* for(int z = 0; z < VOLUME_Z - 1; z++) */
188:
189:
190:        /////////////////////////
191:        // prepare for future scans
192:        if (ftid == 0)
193:        {
194:          unsigned int total_blocks = gridDim.x * gridDim.y * gridDim.z;
195:          unsigned int value = atomicInc (&blocks_done, total_blocks);
196:
197:          //last block
198:          if (value == total_blocks - 1)
199:          {
200:            output_count = min (max_size, global_count);
201:            blocks_done = 0;
202:            global_count = 0;
203:          }
204:        } 
205:      } /* operator () */
206:    };
