{"command":"cat > /tmp/propagate.py <<'PY'
from pathlib import Path
import re
# Small source transformation for free device functions: propagate each view down
# the call graph, passing by value at launches. No CUDA symbol updates are used.
for p in Path('pcl/gpu/people/src/cuda').rglob('*.cu'):
 s=p.read_text()
 if 'thread_local pcl::gpu::TextureView' not in s:continue
 types={m[2]:m[1] for m in re.finditer(r'thread_local (pcl::gpu::TextureView<[^>]+>) (\w+);',s)}
 if p.name=='multi_tree.cu':
  s=s.replace('__constant__ int constFGThresh;', 'thread_local int constFGThresh;')
  s=re.sub(r'cudaSafeCall\s*\(\s*cudaMemcpyToSymbol\s*\(\s*constFGThresh\s*,\s*&FGThresh\s*,.*?\)\s*\)\s*;', 'constFGThresh = FGThresh;',s)
  types['constFGThresh']='int'
 # blank comments preserving positions
 def masked(s):
  return re.sub(r'//[^\n]*|/\*.*?\*/|"(?:\\.|[^"\\])*"',lambda m:' '*len(m[0]),s,flags=re.S)
 z=masked(s)
 def close(pos, a='(',b=')'):
  n=1;i=pos+1
  while n:
   if z[i]==a:n+=1
   if z[i]==b:n-=1
   i+=1
  return i-1
 funcs=[]
 for m in re.finditer(r'\b(?:__device__|__global__)\s+(?:__forceinline__\s+|inline\s+)?[\w:<>]+\s+(\w+)\s*(?:<[^;{}()]*>)?\s*\(',z):
  name=m[1];op=m.end()-1;cl=close(op);end=cl+1
  while z[end].isspace():end+=1
  if z[end]=='{':end=close(end,'{','}')
  else:end=cl
  funcs.append((name,op,cl,end))
 names=set(f[0] for f in funcs)
 needs={name:set() for name in names}
 for name,op,cl,end in funcs:
  for var in types:
   if re.search(r'\b'+var+r'\b',z[cl:end]): needs[name].add(var)
 changed=True
 while changed:
  changed=False
  for name,op,cl,end in funcs:
   for callee in names:
    if re.search(r'\b'+callee+r'\s*(?:<[^;{}()]*>)?\s*\(',z[cl:end]):
     old=len(needs[name]);needs[name]|=needs[callee];changed|=old!=len(needs[name])
 edits={}
 for name,op,cl,end in funcs:
  if needs[name]:edits[op+1]=', '.join(types[v]+' '+v for v in sorted(needs[name]))+(', ' if z[op+1:cl].strip() else '')
 for name in names:
  if not needs[name]:continue
  pattern=r'\b'+name+r'\s*(?:<[^;{}()]*?>)?\s*(?:<<<.*?>>>\s*)?\('
  for m in re.finditer(pattern,z,re.S):
   op=m.end()-1
   if op+1 not in edits:
    edits[op+1]=', '.join(sorted(needs[name]))+', '
 for i,v in sorted(edits.items(),reverse=True):s=s[:i]+v+s[i:]
 print(p, {n:sorted(v) for n,v in needs.items() if v})
 p.write_text(s)
