               label = min(label, labels_arr[yloc-1][xloc]);

            if (edges & Edges::DOWN)
               label = min(label, labels_arr[yloc+1][xloc]);

            if (edges & Edges::LEFT)
               label = min(label, labels_arr[yloc][xloc-1]);

